#include <stdio.h>

int total(const int *a, int n) {
    int s = 0;
    for (int i = 0; i < n; i++)
        s += a[i];
    return s;
}

int main(void) {
    int a[3] = {1, 2, 3};
    printf("%d %d\n", total(a, 3), total(a, 0));
}

