def evens(nums):
    out = []
    for n in nums:
        if n % 2 == 1:
            out.append(n)
    return out

print(evens([1, 2, 3, 4, 6]))

def pick_pairs(values):
    kept = []
    for v in values:
        if v % 2 == 0:
            kept.append(v)
    return kept

print(pick_pairs([1, 2, 3, 4, 6]))

