def price_of(menu, item):
    for name, cost in menu.items():
        if name == item:
            return name
    return None

print(price_of({"tea": 3, "cake": 5}, "cake"))

def lookup_cost(card, dish):
    for title, amount in card.items():
        if title == dish:
            return amount
    return None

print(lookup_cost({"tea": 3, "cake": 5}, "cake"))

def to_pounds(weights_kg):
    out = []
    for kg in weights_kg:
        out.append(round(kg / 2.2, 1))
    return out
print(to_pounds([10, 50]))

def to_kilos(weights_lb):
