def final_score(base, bonuses):
    score = base
    for b in bonuses:
        score *= b
    return score
print(final_score(10, [5, 3]))

def scaled_size(base, factors):
    size = base
    for f in factors:
        size *= f
    return size
print(scaled_size(10, [2, 1.5]))
